<?php
require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/countries.php';
$admin=require_admin();$id=(int)($_GET['id']??0);
$stmt=db()->prepare('SELECT c.*,r.latitude,r.longitude,r.address rescue_address,r.accuracy FROM cases c LEFT JOIN rescue_locations r ON r.id=(SELECT MAX(r2.id) FROM rescue_locations r2 WHERE r2.case_id=c.id) WHERE c.id=? AND c.deleted_at IS NULL');$stmt->execute([$id]);$c=$stmt->fetch();if(!$c){http_response_code(404);exit('Not found');}
$detail=null;if($c['type']==='rescued'){$s=db()->prepare('SELECT * FROM rescued_person_details WHERE case_id=?');$s->execute([$id]);$detail=$s->fetch();}elseif($c['type']==='deceased'){$s=db()->prepare('SELECT * FROM deceased_details WHERE case_id=?');$s->execute([$id]);$detail=$s->fetch();}
$us=db()->prepare('SELECT u.*,a.name admin_name FROM case_updates u LEFT JOIN admins a ON a.id=u.admin_id WHERE u.case_id=? ORDER BY u.created_at,u.id');$us->execute([$id]);$updates=$us->fetchAll();audit($admin['id'],'print_report',$id);
$common=['Case Type / केस प्रकार'=>case_type_label($c['type']),'Case ID'=>$c['case_code'],'Status / अवस्था'=>case_status_label($c['status']).' / '.case_status_label($c['status'],'np'),'Current Condition / हालको अवस्था'=>$c['current_condition']?case_condition_label($c['current_condition']).' / '.case_condition_label($c['current_condition'],'np'):null,'Current Location / हालको स्थान'=>$c['current_location'],'Where Found / कहाँ फेला'=>$c['where_found'],'Shifted To / स्थानान्तरण'=>$c['shifted_to'],'Created / दर्ता'=>$c['created_at'],'Status Updated / अद्यावधिक'=>$c['status_updated_at'],'Close Reason / बन्द कारण'=>$c['close_reason']];
if($c['type']==='rescue_waiting'){$data=['Name / नाम'=>$c['name'],'Address / ठेगाना'=>$c['last_seen_address'],'Mobile No. / मोबाइल नं.'=>$c['family_contact_phone'],'Total Persons / जम्मा व्यक्ति'=>$c['total_persons'],'Situation / परिस्थिति'=>$c['rescue_description'],'Latitude'=>$c['latitude'],'Longitude'=>$c['longitude'],'GPS Accuracy'=>$c['accuracy']!==null?$c['accuracy'].' m':null,'Additional Note / थप नोट'=>$c['additional_notes']]+$common;}
elseif($c['type']==='rescued'&&$detail){$data=['Name / नाम'=>$c['name'],'Identity Status'=>$detail['identity_status'],'Condition / अवस्था'=>rescued_condition_label($detail['condition_level']),'Age'=>$c['age'],'Estimated Age'=>($detail['estimated_age_min']||$detail['estimated_age_max'])?($detail['estimated_age_min']?:'?').'–'.($detail['estimated_age_max']?:'?'):null,'Gender'=>$c['gender'],'Person Phone'=>$detail['person_phone'],'Home Address'=>$detail['permanent_address'],'Workplace'=>$detail['workplace'],'Destination'=>$detail['destination'],'Family / Contact Person'=>$detail['emergency_contact_name'],'Family / Contact Phone'=>$detail['emergency_contact_phone'],'Documents Found'=>$detail['documents_found'],'Document Type'=>$detail['identity_document_type'],'Document Number'=>$detail['identity_document_number'],'Rescue Date/Time'=>$detail['rescue_datetime_gregorian'],'Rescue Date BS'=>$detail['rescue_date_bs'],'Rescue Location'=>$detail['rescue_location'],'Rescued By'=>rescued_by_label($detail['rescued_by_type']),'Rescuer / Responsible Person'=>$detail['rescued_by_name'],'Rescuing Institution'=>$detail['rescuing_institution_name'],'Rescuer Phone'=>$detail['rescuing_institution_phone'],'Injury / Condition'=>$detail['injury_summary'],'Current Institution'=>$detail['current_institution_name'],'Current Institution Address'=>$detail['current_institution_address'],'Institution Contact'=>$detail['institution_contact_name'],'Contact Phone'=>$detail['institution_contact_phone'],'Clothing / Appearance'=>$detail['clothing'],'Marks / Birthmark / Tattoo'=>$detail['distinguishing_marks'],'Belongings'=>$detail['belongings'],'Reunification Status'=>$detail['reunification_status']]+$common;}

elseif($c['type']==='deceased'&&$detail){$data=['Body Trace ID'=>$detail['body_id'],'Identity Status'=>$detail['identity_status'],'Official Identity'=>$detail['official_identity_name'],'Suspected Name'=>$detail['suspected_name'],'Approx. Gender'=>$c['gender'],'Approx. Age'=>$detail['estimated_age_min'],'Body Condition'=>$detail['body_condition'],'Found / Recovery Location'=>$detail['recovery_location'],'River / Waterbody'=>$detail['river_waterbody'],'Recovered By'=>deceased_recovered_by_label($detail['recovered_by_organization']),'Team / Rescuer'=>$detail['recovered_by_name'],'Recovery Date/Time'=>$detail['recovery_datetime_gregorian'],'Recovery Date BS'=>$detail['recovery_date_bs'],'Shifted To Type'=>$detail['shifted_to_type'],'Shifted To'=>$detail['current_mortuary'],'Storage Location'=>$detail['current_storage_location'],'Responsible Officer'=>$detail['recovery_officer_name'],'Responsible Phone'=>$detail['recovery_officer_phone'],'Clothing / Huliya'=>$detail['clothing'],'Tattoos'=>$detail['tattoos'],'Scars'=>$detail['scars'],'Birthmarks'=>$detail['birthmarks'],'Documents Found'=>$detail['documents_found'],'Other Belongings'=>$detail['other_belongings'],'Body Bag No.'=>$detail['body_bag_no'],'Seal No.'=>$detail['seal_no'],'Fingerprint Reference'=>$detail['fingerprint_reference'],'Fingerprint Result'=>$detail['fingerprint_result'],'DNA Sample ID'=>$detail['dna_sample_id'],'DNA Lab'=>$detail['dna_lab'],'DNA Reference'=>$detail['dna_reference'],'DNA Result'=>$detail['dna_result'],'Dental Summary'=>$detail['dental_summary'],'Post-mortem Reference'=>$detail['postmortem_reference'],'Official Identification Method'=>$detail['official_identification_method'],'Forensic Notes'=>$detail['forensic_notes']]+$common;}
else{$data=['Name / नाम'=>$c['name'],'Age / उमेर'=>$c['age'],'Gender / लिङ्ग'=>$c['gender'],'Nationality / राष्ट्रियता'=>$c['nationality_name']?:'Not recorded','Person Category / हैसियत'=>missing_person_context_label($c['missing_person_context']),'Work Institution / Office / Destination / School'=>$c['associated_place_name'],'Document Type'=>$c['nationality_code']&&$c['nationality_code']!=='NP'?identity_document_type_label($c['identity_document_type']):null,'Document Number'=>$c['nationality_code']&&$c['nationality_code']!=='NP'?$c['identity_document_number']:null,'From / ठेगाना'=>$c['from_location'],'Vehicle / सवारी'=>$c['vehicle_no'],'Last Contacted BS / वि.सं.'=>$c['last_contacted_bs'],'Last Contacted Time / समय'=>$c['last_contacted_time'],'Last Contacted Address / अन्तिम सम्पर्क स्थान'=>$c['last_seen_address'],'Other Family Members Missing'=>$c['other_family_members_missing']?'Yes / हो':'No / होइन','Contact / सम्पर्क'=>trim($c['family_contact_name'].' - '.$c['family_contact_phone'],' -'),'Notes / थप विवरण'=>$c['additional_notes']]+$common;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=e($c['case_code'])?> Report</title><link rel="stylesheet" href="<?=e(base_url('assets/app.css'))?>"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&family=Noto+Sans+Devanagari:wght@400;600;700&display=swap" rel="stylesheet"></head><body><main class="container"><div class="no-print" style="padding:15px 0"><button class="btn btn-primary" onclick="window.print()">Print / Save as PDF</button> <button class="btn btn-ghost" onclick="history.back()">Back</button></div><article class="card print-card"><div class="section-title"><div><h1><?=e(case_type_label($c['type']))?> Report / केस प्रतिवेदन</h1><b><?=e($c['case_code'])?></b><?php if($c['type']==='deceased'&&$detail):?><div><b><?=e($detail['body_id'])?></b> · Restricted DVI record</div><?php endif;?></div><div><span class="status status-<?=e($c['status'])?>"><?=e(case_status_label($c['status']))?></span></div></div><?php if($c['photo_url']): $reportPhotoUrl=$c['type']==='deceased'?base_url('admin/media/dvi/'.$id):base_url($c['photo_url']);?><img src="<?=e($reportPhotoUrl)?>" style="width:180px;height:180px;object-fit:cover;border-radius:12px;float:right;margin:0 0 15px 20px"><?php endif;?><div class="case-meta"><?php foreach($data as $k=>$v):if($v!==null&&$v!==''):?><div class="meta-row"><b><?=e($k)?></b><?=nl2br(e((string)$v))?></div><?php endif;endforeach;?></div><div style="clear:both"></div><?php if($updates):?><h2 style="margin-top:24px">Case Progress Timeline / प्रगति विवरण</h2><div class="timeline"><?php foreach($updates as $u):?><div class="timeline-item"><div class="timeline-dot status-dot-<?=e($u['status_after'])?>"></div><div class="timeline-content"><div class="timeline-head"><b><?=e(case_status_label($u['status_after']))?><?php if($u['condition_after']):?> · <?=e(case_condition_label($u['condition_after']))?><?php endif;?></b><time><?=e($u['created_at'])?></time></div><?php if($u['where_found']):?><p><b>Found/Rescued at:</b> <?=e($u['where_found'])?></p><?php endif;?><?php if($u['current_location']):?><p><b>Current location:</b> <?=e($u['current_location'])?></p><?php endif;?><?php if($u['shifted_to']):?><p><b>Shifted to:</b> <?=e($u['shifted_to'])?></p><?php endif;?><?php if($u['note']):?><div class="timeline-note"><?=nl2br(e($u['note']))?></div><?php endif;?><div class="small muted">By <?=e($u['admin_name']?:'Admin')?> · <?= $u['public_visible']?'Public update':'Internal update' ?></div></div></div><?php endforeach;?></div><?php endif;?><p class="small muted">Generated <?=e(date('Y-m-d H:i:s'))?> by <?=e($admin['name'])?></p></article></main></body></html>
